    value = str(value);
    if (
        (value.lower() == 'true')
        or (value.lower() == 't')
        or (value.lower() == 'yes')
        or (value.lower() == 'y')
        or (value.lower() == '1')
    ) {
        return True;
    }
    if (
        (value.lower() == 'false')
        or (value.lower() == 'f')
        or (value.lower() == 'no')
        or (value.lower() == 'n')
        or (value.lower() == '0')
    ) {
        return False;
    }
    return None;
}

